for row_idx in range(5):
    row = []
    for col_idx in range(5):
        if row_idx <= col_idx:
            row.append(pattern[col_idx])  # pattern at this column
        else:
            row.append(0)  # or 9
    output_below_diag.append(row)

output_below_diag.append([2, 2, 2, 2, 2])
output_below_diag.append([4, 3, 5, 7, 2])

